package com.creatorflow;

import com.fasterxml.jackson.databind.*;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;

@Service
class CodingExecutions {
    record Create(@NotNull UUID workspaceId,@NotNull @Pattern(regexp="CODEX_EXECUTE") String taskType,
        @NotNull @Pattern(regexp="CODEX_CLI") String provider,@NotBlank @Size(max=2000) String objective,
        @NotNull @Size(min=1,max=10) List<@NotBlank @Size(max=160) String> allowedFiles,
        @NotNull UUID budgetPolicyId,@Min(5) @Max(60) int timeoutSec,@Min(1) @Max(1) int maxAttempts,
        @NotNull @Pattern(regexp="[A-Za-z0-9_-]{1,64}") String requestKey) {}
    record Authorize(@NotNull @Pattern(regexp="[a-f0-9]{64}") String contractHash,@NotNull @Pattern(regexp="AUTHORIZE_CODEX") String confirmation,@Min(2) @Max(15) int expiresInMinutes) {}
    record Capability(@NotNull UUID sessionId,@Pattern(regexp="[A-Za-z0-9.+_-]{1,40}") String cliVersion,boolean protocolSupported,boolean sandboxVerified,
        @Pattern(regexp="[A-Z0-9_]{1,48}") String errorCode,@NotNull @Pattern(regexp="[a-f0-9]{64}") String evidenceHash) {}
    record Attempt(@NotNull UUID sessionId,@Min(1) @Max(1) int attempt) {}
    record Result(@NotNull UUID sessionId,@Min(1) @Max(1) int attempt,@NotNull UUID checkpointId,
        @NotNull @Pattern(regexp="REVIEW_REQUIRED|FAILED|CANCELLED|NEEDS_RECONCILIATION") String state,
        @Size(max=131072) String diff,@NotNull @Size(max=10) List<@Size(max=160) String> changedFiles,
        @NotNull @Pattern(regexp="[a-f0-9]{64}") String diffSha256,@NotNull @Pattern(regexp="[a-f0-9]{64}") String evidenceHash,
        @Pattern(regexp="[A-Z0-9_]{1,48}") String errorCode) {}
    final JdbcTemplate db;final AgentQueue queue;final CodingRegistry registry;final CodingWorkspaces workspaces;final CodingAdmission admission;final ObjectMapper json;final boolean enabled;
    CodingExecutions(JdbcTemplate db,AgentQueue queue,CodingRegistry registry,CodingWorkspaces workspaces,CodingAdmission admission,ObjectMapper json,@Value("${creatorflow.codex-execution-enabled:false}") boolean enabled){this.db=db;this.queue=queue;this.registry=registry;this.workspaces=workspaces;this.admission=admission;this.json=json;this.enabled=enabled;}
    void event(UUID id,String type,String actor){db.update("insert into coding_execution_events(execution_id,type,actor) values (?,?,?)",id,type,actor);}
    Map<String,Object> row(UUID id){var rows=db.queryForList("select * from coding_executions where id=?",id);if(rows.isEmpty())throw AgentQueue.conflict("Execution not found");return rows.getFirst();}
    Map<String,Object> contract(Map<String,Object> e){try{return json.readValue(e.get("contract").toString(),Map.class);}catch(Exception ex){throw AgentQueue.conflict("Invalid execution contract");}}
    Map<String,Object> view(UUID id){var e=new LinkedHashMap<>(row(id));e.put("contract",contract(e));if(e.get("changed_files")!=null)try{e.put("changed_files",json.readValue(e.get("changed_files").toString(),List.class));}catch(Exception ex){throw AgentQueue.conflict("Invalid evidence");}return e;}
    Map<String,Object> inventory(){return Map.of("executionEnabled",enabled,"liveVerification","NOT_VERIFIED","executions",db.queryForList("select id from coding_executions order by created_at desc limit 100").stream().map(r->view((UUID)r.get("id"))).toList(),"capabilities",db.queryForList("select * from coding_execution_capabilities"),"authorizations",db.queryForList("select * from coding_execution_authorizations order by issued_at desc limit 100"),"events",db.queryForList("select * from coding_execution_events order by id desc limit 100"));}
    static void file(String file){CodingWorkspaces.relative(file);if(!file.matches("[A-Za-z0-9_-]+(?:[./][A-Za-z0-9_-]+)*") || file.endsWith(".") || file.length()>160 || Arrays.stream(file.split("/")).anyMatch(p->p.toLowerCase(Locale.ROOT).matches("(?:con|prn|aux|nul|com[0-9]|lpt[0-9])(?:\\..*)?")) || file.toLowerCase(Locale.ROOT).matches(".*(?:^|/)(?:agents\\.md|package\\.json|.*\\.lock|.*\\.(?:exe|dll|cmd|bat|ps1|pem|key))$"))throw AgentQueue.conflict("Unsupported exact file scope");}
    void lock(UUID agent){db.queryForList("select id from local_agents where id=? for update",agent);}
    String budgetFingerprint(UUID id){return AgentIdentity.hash(registry.encode(new TreeMap<>(db.queryForMap("select * from coding_budget_policies where id=?",id))));}
    void noFoundationWriter(UUID workspace){if(db.queryForObject("select count(*) from coding_workspaces w join agent_tasks t on t.id=w.current_task_id where w.id=? and t.state in ('QUEUED','RUNNING','CANCEL_REQUESTED')",Integer.class,workspace)>0)throw AgentQueue.conflict("Foundation operation still active");}
    void validateDiff(Result in){
        if(in.diff()==null || in.diff().isEmpty()){if(!in.changedFiles().isEmpty())throw AgentQueue.conflict("Missing diff");return;}
        var paths=new HashSet<String>();
        for(String line:in.diff().split("\\n"))if(line.startsWith("diff --git ")){
            var m=java.util.regex.Pattern.compile("diff --git a/([A-Za-z0-9_./-]+) b/([A-Za-z0-9_./-]+)").matcher(line);
            if(!m.matches() || !m.group(1).equals(m.group(2)))throw AgentQueue.conflict("Invalid diff paths");file(m.group(1));paths.add(m.group(1));
        }
        if(!paths.equals(new HashSet<>(in.changedFiles())) || in.diff().contains("GIT binary patch") || in.diff().contains("new file mode") || in.diff().contains("deleted file mode") || in.diff().contains("old mode"))throw AgentQueue.conflict("Diff scope/type mismatch");
    }
    @Transactional Map<String,Object> create(Create in,String actor){
        ContentManifests.operator(actor);in.allowedFiles().forEach(CodingExecutions::file);if(in.allowedFiles().stream().map(s->s.toLowerCase(Locale.ROOT)).distinct().count()!=in.allowedFiles().size())throw AgentQueue.conflict("Duplicate file scope");
        var w=workspaces.workspace(in.workspaceId());UUID agent=(UUID)w.get("agent_id");lock(agent);w=workspaces.workspace(in.workspaceId());var r=workspaces.eligible((UUID)w.get("repository_id"));
        if(!"READY".equals(w.get("state")) || Boolean.TRUE.equals(w.get("writer_locked")) || w.get("last_checkpoint_id")==null || db.queryForObject("select count(*) from agent_tasks where id=? and state in ('QUEUED','RUNNING','CANCEL_REQUESTED')",Integer.class,w.get("current_task_id"))>0)throw AgentQueue.conflict("Workspace needs clean committed READY checkpoint");
        if(db.queryForObject("select count(*) from coding_budget_policies where id=? and agent_id=? and provider='CODEX_CLI'",Integer.class,in.budgetPolicyId(),agent)!=1)throw AgentQueue.conflict("Exact provider budget policy required");
        var c=new TreeMap<String,Object>();c.put("task",in);c.put("budgetPolicyHash",budgetFingerprint(in.budgetPolicyId()));c.put("repositoryId",w.get("repository_id"));c.put("repositoryConfigHash",r.get("configHash"));c.put("agentId",agent);c.put("baseCommit",w.get("base_commit"));c.put("checkpointId",w.get("last_checkpoint_id"));c.put("prohibitedPaths",List.of(".git/**",".codex/**",".aws/**","**/.env*","**/AGENTS.md"));
        String encoded=registry.encode(c),hash=AgentIdentity.hash(encoded);var old=db.queryForList("select id,contract_hash from coding_executions where request_key=?",in.requestKey());if(!old.isEmpty()){if(!hash.equals(old.getFirst().get("contract_hash")))throw AgentQueue.conflict("Execution idempotency collision");return view((UUID)old.getFirst().get("id"));}
        UUID id=UUID.randomUUID();db.update("insert into coding_executions(id,workspace_id,agent_id,request_key,contract,contract_hash) values (?,?,?,?,?::jsonb,?)",id,in.workspaceId(),agent,in.requestKey(),encoded,hash);event(id,"DRAFT_CREATED",actor);return view(id);
    }
    void workspaceBinding(Map<String,Object> e){var w=workspaces.workspace((UUID)e.get("workspace_id"));var c=contract(e);var r=workspaces.eligible((UUID)w.get("repository_id"));if(!c.get("baseCommit").equals(w.get("base_commit")) || !c.get("checkpointId").toString().equals(Objects.toString(w.get("last_checkpoint_id"))) || !c.get("repositoryConfigHash").equals(r.get("configHash")) || !List.of("READY","EXECUTING").contains(w.get("state")))throw AgentQueue.conflict("Workspace approval binding changed");}
    @Transactional Map<String,Object> authorize(UUID id,Authorize in,String actor){ContentManifests.operator(actor);var e=row(id);lock((UUID)e.get("agent_id"));e=row(id);if(!in.contractHash().equals(e.get("contract_hash")))throw AgentQueue.conflict("Exact contract confirmation required");if("AUTHORIZED".equals(e.get("state")))return view(id);if(!List.of("DRAFT","BLOCKED").contains(e.get("state")))throw AgentQueue.conflict("Execution cannot be reauthorized");workspaceBinding(e);
        var credential=db.queryForMap("select generation,revoked_at from agent_credentials where agent_id=?",e.get("agent_id"));if(credential.get("revoked_at")!=null)throw AgentQueue.conflict("Agent revoked; enroll a new identity");UUID authorization=UUID.randomUUID();db.update("insert into coding_execution_authorizations(id,execution_id,contract_hash,credential_generation,operator_id,expires_at) values (?,?,?,?,?,now()+make_interval(mins=>?))",authorization,id,in.contractHash(),credential.get("generation"),actor,in.expiresInMinutes());db.update("update coding_executions set state='AUTHORIZED',authorization_id=?,error_code=null,updated_at=now() where id=?",authorization,id);event(id,"OPERATOR_AUTHORIZED",actor);return view(id);}
    @Transactional Map<String,Object> cancel(UUID id,String actor){ContentManifests.operator(actor);var e=row(id);lock((UUID)e.get("agent_id"));e=row(id);String state=e.get("state").toString();if(List.of("DRAFT","BLOCKED","AUTHORIZED","CLAIMED","RUNNING","CANCEL_REQUESTED").contains(state)){String next=List.of("RUNNING","CANCEL_REQUESTED").contains(state)?"CANCEL_REQUESTED":"CANCELLED";db.update("update coding_executions set state=?,updated_at=now() where id=?",next,id);if(e.get("authorization_id")!=null)db.update("update coding_execution_authorizations set revoked_at=coalesce(revoked_at,now()) where id=?",e.get("authorization_id"));if(next.equals("CANCELLED"))release(e,false);event(id,next,actor);}return view(id);}
    @Transactional Map<String,Object> capability(UUID agent,Capability in){queue.current(agent,in.sessionId());if(in.sandboxVerified()&&(!in.protocolSupported()||in.cliVersion()==null||in.errorCode()!=null))throw AgentQueue.conflict("Inconsistent sandbox evidence");db.update("insert into coding_execution_capabilities values (?,?,?,?,?,?,?,now()) on conflict(agent_id) do update set session_id=excluded.session_id,cli_version=excluded.cli_version,protocol_supported=excluded.protocol_supported,sandbox_verified=excluded.sandbox_verified,error_code=excluded.error_code,evidence_hash=excluded.evidence_hash,observed_at=now()",agent,in.sessionId(),in.cliVersion(),in.protocolSupported(),in.sandboxVerified(),in.errorCode(),in.evidenceHash());return Map.of("accepted",true);}
    String gate(Map<String,Object> e,UUID session){
        if(!enabled)return "EXECUTOR_DISABLED";
        try{noFoundationWriter((UUID)e.get("workspace_id"));workspaceBinding(e);}catch(org.springframework.web.server.ResponseStatusException ex){return "WORKSPACE_BINDING_CHANGED";}UUID agent=(UUID)e.get("agent_id");
        if(db.queryForObject("select count(*) from coding_execution_authorizations a join agent_credentials c on c.agent_id=? where a.id=? and a.execution_id=? and a.contract_hash=? and a.credential_generation=c.generation and c.revoked_at is null and a.revoked_at is null and a.expires_at>now()+make_interval(secs=>?)",Integer.class,agent,e.get("authorization_id"),e.get("id"),e.get("contract_hash"),((Number)((Map<?,?>)contract(e).get("task")).get("timeoutSec")).intValue())!=1)return "AUTHORIZATION_EXPIRED_OR_FENCED";
        if(db.queryForObject("select count(*) from coding_execution_capabilities where agent_id=? and session_id=? and protocol_supported and sandbox_verified and observed_at>now()-interval '60 seconds'",Integer.class,agent,session)!=1)return "SANDBOX_NOT_VERIFIED";
        var task=(Map<?,?>)contract(e).get("task");UUID policy=UUID.fromString(task.get("budgetPolicyId").toString());if(db.queryForObject("select count(*) from coding_budget_policies where id=? and agent_id=? and provider='CODEX_CLI'",Integer.class,policy,agent)!=1 || !budgetFingerprint(policy).equals(contract(e).get("budgetPolicyHash")))return "BUDGET_POLICY_CHANGED";
        if(e.get("admission_id")!=null)db.update("update coding_admissions set reserved_until=now() where id=?",e.get("admission_id"));
        var check=admission.check(new CodingAdmission.Check(UUID.randomUUID(),agent,CodingAdmission.Provider.CODEX_CLI,((Number)task.get("timeoutSec")).intValue(),1,true),"local-user");if(!"READY".equals(check.get("state")))return check.get("state").toString();db.update("update coding_executions set admission_id=? where id=?",check.get("id"),e.get("id"));return null;
    }
    @Transactional Map<String,Object> claim(UUID agent,UUID session){queue.current(agent,session);if(db.queryForObject("select count(*) from agent_tasks where agent_id=? and state in ('RUNNING','CANCEL_REQUESTED')",Integer.class,agent)>0 || db.queryForObject("select count(*) from coding_executions where agent_id=? and state in ('CLAIMED','RUNNING','CANCEL_REQUESTED')",Integer.class,agent)>0)return Map.of();var rows=db.queryForList("select id from coding_executions where agent_id=? and state='AUTHORIZED' order by created_at limit 1 for update",agent);if(rows.isEmpty())return Map.of();UUID id=(UUID)rows.getFirst().get("id");var e=row(id);String error=gate(e,session);if(error!=null){db.update("update coding_executions set state='BLOCKED',error_code=? where id=?",error,id);event(id,"BLOCKED_"+error,"agent");return Map.of();}db.update("update coding_executions set state='CLAIMED',session_id=?,attempt=1,lease_expires_at=now()+interval '12 seconds',updated_at=now() where id=?",session,id);db.update("update coding_workspaces set writer_locked=true,owner_session=?,owner_attempt=1,lease_expires_at=now()+interval '12 seconds',state='EXECUTING' where id=?",session,e.get("workspace_id"));event(id,"CLAIMED","agent");return view(id);}
    Map<String,Object> active(UUID agent,UUID id,Attempt in){queue.current(agent,in.sessionId());var e=row(id);if(!agent.equals(e.get("agent_id")) || !in.sessionId().equals(e.get("session_id")) || !List.of("CLAIMED","RUNNING","CANCEL_REQUESTED").contains(e.get("state")) || db.queryForObject("select count(*) from coding_executions where id=? and lease_expires_at>now()",Integer.class,id)!=1)throw AgentQueue.conflict("Execution session/lease fenced");return e;}
    @Transactional Map<String,Object> begin(UUID agent,UUID id,Attempt in){var e=active(agent,id,in);if(!"CLAIMED".equals(e.get("state")))throw AgentQueue.conflict("Execution start is single use; reconcile lost response");String error=gate(e,in.sessionId());if(error!=null){db.update("update coding_executions set state='BLOCKED',error_code=? where id=?",error,id);release(e,false);event(id,"BLOCKED_"+error,"agent");return Map.of("permitted",false,"errorCode",error);}db.update("update coding_executions set state='RUNNING',started_at=now(),updated_at=now() where id=?",id);event(id,"RUNNING","agent");return Map.of("permitted",true,"contractHash",e.get("contract_hash"));}
    @Transactional Map<String,Object> renew(UUID agent,UUID id,Attempt in){var e=active(agent,id,in);int timeout=((Number)((Map<?,?>)contract(e).get("task")).get("timeoutSec")).intValue();boolean deadline=e.get("started_at")!=null && ((java.sql.Timestamp)e.get("started_at")).toInstant().plusSeconds(timeout).isBefore(Instant.now());boolean revoked=db.queryForObject("select count(*) from coding_execution_authorizations where id=? and revoked_at is null and expires_at>now()",Integer.class,e.get("authorization_id"))!=1;boolean cancel=deadline||revoked||"CANCEL_REQUESTED".equals(e.get("state"));db.update("update coding_executions set lease_expires_at=now()+interval '12 seconds' where id=?",id);db.update("update coding_workspaces set lease_expires_at=now()+interval '12 seconds' where id=?",e.get("workspace_id"));return Map.of("cancelRequested",cancel,"leaseSeconds",12);}
    void release(Map<String,Object> e,boolean uncertain){if(e.get("admission_id")!=null)db.update("update coding_admissions set reserved_until=now() where id=?",e.get("admission_id"));db.update("update coding_workspaces set writer_locked=false,lease_expires_at=null,state=? where id=?",uncertain?"NEEDS_RECONCILIATION":"READY",e.get("workspace_id"));}
    @Transactional Map<String,Object> result(UUID agent,UUID id,Result in){var e=active(agent,id,new Attempt(in.sessionId(),in.attempt()));if(!List.of("RUNNING","CANCEL_REQUESTED").contains(e.get("state")))throw AgentQueue.conflict("No execution began");validateDiff(in);var scope=(List<?>)((Map<?,?>)contract(e).get("task")).get("allowedFiles");String diff=in.diff()==null?"":in.diff();if(!AgentIdentity.hash(diff).equals(in.diffSha256()) || !scope.containsAll(in.changedFiles()) || in.changedFiles().stream().distinct().count()!=in.changedFiles().size() || diff.matches("(?s).*(?:Bearer [A-Za-z0-9_-]{20,}|sk-[A-Za-z0-9_-]{20,}|-----BEGIN .*PRIVATE KEY-----).*"))throw AgentQueue.conflict("Invalid or sensitive execution evidence");if("REVIEW_REQUIRED".equals(in.state()) && (in.errorCode()!=null || in.changedFiles().isEmpty() || diff.isBlank() || !"RUNNING".equals(e.get("state"))))throw AgentQueue.conflict("Invalid review result");String state="CANCEL_REQUESTED".equals(e.get("state"))?"CANCELLED":in.state();db.update("update coding_executions set state=?,checkpoint_id=?,diff=?,changed_files=?::jsonb,diff_sha256=?,evidence_hash=?,error_code=?,lease_expires_at=null,updated_at=now() where id=?",state,in.checkpointId(),diff,registry.encode(in.changedFiles()),in.diffSha256(),in.evidenceHash(),in.errorCode(),id);release(e,true);if("REVIEW_REQUIRED".equals(state))db.update("update coding_workspaces set state='REVIEW_REQUIRED' where id=?",e.get("workspace_id"));event(id,state,"agent");return view(id);}
    @Scheduled(fixedDelay=1000) @Transactional public void recover(){for(var r:db.queryForList("select id,agent_id from coding_executions where state in ('CLAIMED','RUNNING','CANCEL_REQUESTED') and lease_expires_at<=now()")){lock((UUID)r.get("agent_id"));var e=row((UUID)r.get("id"));if(db.update("update coding_executions set state='NEEDS_RECONCILIATION',error_code='LEASE_EXPIRED',lease_expires_at=null where id=? and state in ('CLAIMED','RUNNING','CANCEL_REQUESTED') and lease_expires_at<=now()",e.get("id"))==1){release(e,true);event((UUID)e.get("id"),"LEASE_EXPIRED","recovery");}}}
}

@RestController
class CodingExecutionApi {
    final CodingExecutions service;final CodingWorkspaces validation;
    CodingExecutionApi(CodingExecutions service,CodingWorkspaces validation){this.service=service;this.validation=validation;}
    @GetMapping("/api/v2/coding/executions") Map<String,Object> inventory(){return service.inventory();}
    @PostMapping("/api/v2/coding/executions") Map<String,Object> create(@RequestBody JsonNode in,Authentication auth){return service.create(validation.strict(in,CodingExecutions.Create.class,Set.of("workspaceId","taskType","provider","objective","allowedFiles","budgetPolicyId","timeoutSec","maxAttempts","requestKey")),auth.getName());}
    @PostMapping("/api/v2/coding/executions/{id}/authorize") Map<String,Object> authorize(@PathVariable UUID id,@Valid @RequestBody CodingExecutions.Authorize in,Authentication auth){return service.authorize(id,in,auth.getName());}
    @PostMapping("/api/v2/coding/executions/{id}/cancel") Map<String,Object> cancel(@PathVariable UUID id,Authentication auth){return service.cancel(id,auth.getName());}
    @PostMapping("/api/v2/agent-runtime/coding/executions/capability") Map<String,Object> capability(@Valid @RequestBody CodingExecutions.Capability in,Authentication auth){return service.capability((UUID)auth.getPrincipal(),in);}
    @PostMapping("/api/v2/agent-runtime/coding/executions/claim") Map<String,Object> claim(@Valid @RequestBody AgentApi.SessionRequest in,Authentication auth){return service.claim((UUID)auth.getPrincipal(),in.sessionId());}
    @PostMapping("/api/v2/agent-runtime/coding/executions/{id}/begin") Map<String,Object> begin(@PathVariable UUID id,@Valid @RequestBody CodingExecutions.Attempt in,Authentication auth){return service.begin((UUID)auth.getPrincipal(),id,in);}
    @PostMapping("/api/v2/agent-runtime/coding/executions/{id}/renew") Map<String,Object> renew(@PathVariable UUID id,@Valid @RequestBody CodingExecutions.Attempt in,Authentication auth){return service.renew((UUID)auth.getPrincipal(),id,in);}
    @PostMapping("/api/v2/agent-runtime/coding/executions/{id}/result") Map<String,Object> result(@PathVariable UUID id,@Valid @RequestBody CodingExecutions.Result in,Authentication auth){return service.result((UUID)auth.getPrincipal(),id,in);}
}
